                Emit(Op::LoadReference,0,item);Emit(Op::GetProperty,0,binding.first);
                if(declareItem)Emit(Op::Declare,functionScoped?1:immutable?3:0,binding.second);
                else{Emit(Op::Assign);Emit(Op::Pop);}
