        ++scriptJobs;scriptJobMilliseconds+=duration;
        scriptCpuTicks+=cpu;longestScriptCpuTicks=std::max(longestScriptCpuTicks,cpu);
        longestScriptJobMilliseconds=std::max(longestScriptJobMilliseconds,duration);
