            case Op::BitwiseAnd:case Op::BitwiseOr:case Op::BitwiseXor:case Op::ShiftLeft:case Op::ShiftRight:case Op::UnsignedShiftRight:
            case Op::Equal:case Op::NotEqual:case Op::StrictEqual:case Op::StrictNotEqual:
