void JavaScriptRuntime::SetViewportSize(double width,double height){
    impl_->core.viewportWidth=std::max(0.0,width);impl_->core.viewportHeight=std::max(0.0,height);
    const auto widthValue=Value::Number(impl_->core.viewportWidth),heightValue=Value::Number(impl_->core.viewportHeight);
    impl_->core.global->values[L"innerWidth"]=widthValue;impl_->core.global->values[L"innerHeight"]=heightValue;
    const auto found=impl_->core.global->values.find(L"window");
    if(found!=impl_->core.global->values.end()&&found->second.type==Value::Type::Object&&found->second.object){
        found->second.object->props[L"innerWidth"]=widthValue;
        found->second.object->props[L"innerHeight"]=heightValue;
    }
    const auto screen=impl_->core.global->values.find(L"screen");
    if(screen!=impl_->core.global->values.end()&&screen->second.object){
        const auto screenWidth=Value::Number(std::round(impl_->core.displayWidth>0?impl_->core.displayWidth:impl_->core.viewportWidth));
        const auto screenHeight=Value::Number(std::round(impl_->core.displayHeight>0?impl_->core.displayHeight:impl_->core.viewportHeight));
        screen->second.object->props[L"$host:width"]=screenWidth;
        screen->second.object->props[L"$host:height"]=screenHeight;
        screen->second.object->props[L"$host:availWidth"]=impl_->core.availableDisplayWidth>=0?Value::Number(std::round(impl_->core.availableDisplayWidth)):screenWidth;
        screen->second.object->props[L"$host:availHeight"]=impl_->core.availableDisplayHeight>=0?Value::Number(std::round(impl_->core.availableDisplayHeight)):screenHeight;
    }
    impl_->core.UpdateMediaQueries();
}
void JavaScriptRuntime::SetDevicePixelRatio(double ratio){
    impl_->core.devicePixelRatio=std::isfinite(ratio)&&ratio>0?ratio:1;
    const auto value=Value::Number(impl_->core.devicePixelRatio);
    impl_->core.global->values[L"devicePixelRatio"]=value;
    const auto found=impl_->core.global->values.find(L"window");
    if(found!=impl_->core.global->values.end()&&found->second.object)
        found->second.object->props[L"devicePixelRatio"]=value;
    impl_->core.UpdateMediaQueries();
}
void JavaScriptRuntime::SetDisplaySize(double width,double height){
    SetDisplaySize(width,height,width,height);
}
void JavaScriptRuntime::SetDisplaySize(double width,double height,double availableWidth,double availableHeight){
    auto& core=impl_->core;core.displayWidth=std::max(0.0,width);core.displayHeight=std::max(0.0,height);
    core.availableDisplayWidth=std::max(0.0,std::min(core.displayWidth,availableWidth));
    core.availableDisplayHeight=std::max(0.0,std::min(core.displayHeight,availableHeight));
    const auto screen=core.global->values.find(L"screen");
    if(screen!=core.global->values.end()&&screen->second.object){
        screen->second.object->props[L"$host:width"]=Value::Number(std::round(core.displayWidth));
        screen->second.object->props[L"$host:height"]=Value::Number(std::round(core.displayHeight));
        screen->second.object->props[L"$host:availWidth"]=Value::Number(std::round(core.availableDisplayWidth));
        screen->second.object->props[L"$host:availHeight"]=Value::Number(std::round(core.availableDisplayHeight));
    }
    core.UpdateMediaQueries();
}
void JavaScriptRuntime::SetLocation(const std::wstring& location){
    auto& core=impl_->core;core.UpdateLocation(location);
    for(auto& binding:core.storageBindings)binding.area->Unsubscribe(binding.subscription);core.storageBindings.clear();
    if(core.CurrentOrigin()!=L"null")for(const auto* name:{L"localStorage",L"sessionStorage"})core.StorageFor(core.global->values[name].object);
    const auto found=core.global->values.find(L"history");
    if(found!=core.global->values.end()&&found->second.object&&found->second.object->items.size()==1)
        found->second.object->items.front().object->props[L"url"]=Value::String(location);
}
void JavaScriptRuntime::SetWindowName(const std::wstring& name){
    auto& core=impl_->core;core.windowName=name;
    const auto found=core.global->values.find(L"window");
    if(found!=core.global->values.end()&&found->second.object)
        found->second.object->props[L"name"]=Value::String(name);
}
